import { Field } from '@base-ui/react/field';
import { Clock } from 'lucide-react';
import { useRef, useState, type ComponentProps, type KeyboardEvent, type MouseEvent } from 'react';
import { useI18n, useOptionalI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { timePickerVariants, type TimePickerVariantProps } from './time-picker.variants';
import { dayPeriodLabels, formatTimeOfDay, localeHourCycle, parseTimeOfDay, timeToSeconds } from './time-utils';

export interface TimePickerProps extends TimePickerVariantProps {
  /** `"HH:mm"` (or `"HH:mm:ss"` with `withSeconds`), 24-hour clock; `null` while incomplete. */
  value?: string | null;
  defaultValue?: string | null;
  /** Fires with a complete time, or `null` when a segment is cleared. */
  onValueChange?: (value: string | null) => void;
  /** Adds a seconds segment. */
  withSeconds?: boolean;
  /** 12-hour (with an AM/PM segment) or 24-hour clock. Defaults to the locale's. */
  hourCycle?: 12 | 24;
  /** BCP 47 locale for the hour cycle and AM/PM labels. Defaults to the I18nProvider's. */
  locale?: string;
  /** Minute increment for the arrow keys (e.g. 15). Typed minutes are not snapped. */
  step?: number;
  /** Earliest valid time (`"HH:mm"`); earlier values are marked invalid. */
  min?: string;
  /** Latest valid time (`"HH:mm"`). */
  max?: string;
  /** Submitted as `HH:mm[:ss]` through a hidden input. */
  name?: string;
  id?: string;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  /** Show the leading clock icon. */
  icon?: boolean;
  className?: string;
  'aria-label'?: string;
  'aria-labelledby'?: string;
  'aria-describedby'?: string;
}

type SegmentKey = 'hour' | 'minute' | 'second' | 'period';

interface Draft {
  /** 0–23. */
  hour: number | null;
  minute: number | null;
  second: number | null;
  /** AM/PM picked before the hour (12-hour clock). */
  pm: boolean | null;
}

const EMPTY: Draft = { hour: null, minute: null, second: null, pm: null };

function toDraft(value: string | null | undefined): Draft {
  const t = parseTimeOfDay(value);
  return t ? { hour: t.hours, minute: t.minutes, second: t.seconds, pm: t.hours >= 12 } : EMPTY;
}

function draftToValue(d: Draft, withSeconds: boolean): string | null {
  if (d.hour === null || d.minute === null || (withSeconds && d.second === null)) return null;
  return formatTimeOfDay({ hours: d.hour, minutes: d.minute, seconds: d.second ?? 0 }, withSeconds);
}

const pad = (n: number) => String(n).padStart(2, '0');

/**
 * Time field: hour, minute (optional second, AM/PM on a 12-hour clock) spinbutton segments.
 * Arrows spin the focused segment (minutes by `step`), digits type into it and auto-advance,
 * Backspace clears it, ArrowLeft/ArrowRight move between segments. Works inside Field.
 */
export function TimePicker({
  value,
  defaultValue,
  onValueChange,
  withSeconds = false,
  hourCycle: hourCycleProp,
  locale: localeProp,
  step = 1,
  min,
  max,
  name,
  id,
  disabled,
  readOnly,
  invalid,
  icon = true,
  size = 'auto',
  className,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledBy,
  'aria-describedby': ariaDescribedBy,
}: TimePickerProps) {
  const { t } = useI18n();
  const providerLocale = useOptionalI18n()?.locale;
  const locale = localeProp ?? providerLocale;
  const hourCycle = hourCycleProp ?? localeHourCycle(locale);
  const [amLabel, pmLabel] = dayPeriodLabels(locale);
  const controlled = value !== undefined;
  const [draft, setDraft] = useState<Draft>(() => toDraft(controlled ? value : defaultValue));
  const [synced, setSynced] = useState(value);
  // A new controlled value (not the echo of our own change) replaces the draft.
  if (controlled && value !== synced) {
    setSynced(value);
    setDraft(toDraft(value));
  }
  const buffer = useRef<{ key: SegmentKey; text: string } | null>(null);
  const segmentRefs = useRef<Array<HTMLDivElement | null>>([]);
  const s = timePickerVariants({ size });
  const minuteStep = Math.max(1, Math.floor(step));

  const keys: SegmentKey[] = ['hour', 'minute', ...(withSeconds ? (['second'] as const) : []), ...(hourCycle === 12 ? (['period'] as const) : [])];
  const current = draftToValue(draft, withSeconds);
  const parsed = parseTimeOfDay(current);
  const minT = parseTimeOfDay(min);
  const maxT = parseTimeOfDay(max);
  const outOfRange = !!parsed && ((!!minT && timeToSeconds(parsed) < timeToSeconds(minT)) || (!!maxT && timeToSeconds(parsed) > timeToSeconds(maxT)));

  const periodFlag = draft.hour !== null ? draft.hour >= 12 : draft.pm;
  const display = (key: SegmentKey): number | null => {
    if (key === 'hour') return draft.hour === null ? null : hourCycle === 12 ? draft.hour % 12 || 12 : draft.hour;
    if (key === 'minute') return draft.minute;
    if (key === 'second') return draft.second;
    return periodFlag === null ? null : periodFlag ? 1 : 0;
  };
  const range = (key: SegmentKey): [number, number] =>
    key === 'hour' ? (hourCycle === 12 ? [1, 12] : [0, 23]) : key === 'period' ? [0, 1] : [0, 59];

  const withSegment = (d: Draft, key: SegmentKey, n: number | null): Draft => {
    if (key === 'minute') return { ...d, minute: n };
    if (key === 'second') return { ...d, second: n };
    if (key === 'period') {
      const pm = n === null ? null : n === 1;
      return { ...d, pm, hour: d.hour === null || pm === null ? d.hour : (d.hour % 12) + (pm ? 12 : 0) };
    }
    if (n === null) return { ...d, hour: null, pm: periodFlag };
    if (hourCycle === 24) return { ...d, hour: n };
    return { ...d, hour: (n % 12) + (periodFlag ? 12 : 0) };
  };

  const commit = (next: Draft) => {
    setDraft(next);
    const v = draftToValue(next, withSeconds);
    if (v !== current) {
      if (controlled) setSynced(v);
      onValueChange?.(v);
    }
  };

  const focusSegment = (i: number) => {
    buffer.current = null;
    segmentRefs.current[Math.max(0, Math.min(keys.length - 1, i))]?.focus();
  };

  const spin = (key: SegmentKey, delta: number) => {
    const [lo, hi] = range(key);
    const cur = display(key);
    const stepSize = key === 'minute' ? minuteStep : 1;
    const top = Math.floor(hi / stepSize) * stepSize;
    let next: number;
    if (cur === null) next = delta > 0 ? lo : top;
    else if (stepSize > 1) next = delta > 0 ? (Math.floor(cur / stepSize) + 1) * stepSize : (Math.ceil(cur / stepSize) - 1) * stepSize;
    else next = cur + delta;
    if (next > hi) next = lo;
    if (next < lo) next = top;
    commit(withSegment(draft, key, next));
  };

  const typeDigit = (key: SegmentKey, index: number, digit: string) => {
    const [lo, hi] = range(key);
    let text = (buffer.current?.key === key ? buffer.current.text : '') + digit;
    let n = Number(text);
    if (n > hi) {
      text = digit;
      n = Number(digit);
    }
    if (n >= lo) commit(withSegment(draft, key, n));
    else if (text.length >= 2) commit(withSegment(draft, key, hi)); // "00" on a 12-hour clock → 12
    if (text.length >= 2 || n * 10 > hi) focusSegment(index + 1);
    else buffer.current = { key, text };
  };

  const onKeyDown = (key: SegmentKey, index: number) => (e: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    const editable = !readOnly;
    let handled = true;
    if (e.key === 'ArrowLeft') focusSegment(index - 1);
    else if (e.key === 'ArrowRight') focusSegment(index + 1);
    else if (!editable) handled = false;
    else if (e.key === 'ArrowUp') spin(key, 1);
    else if (e.key === 'ArrowDown') spin(key, -1);
    else if (e.key === 'Home') commit(withSegment(draft, key, range(key)[0]));
    else if (e.key === 'End') commit(withSegment(draft, key, key === 'minute' ? Math.floor(59 / minuteStep) * minuteStep : range(key)[1]));
    else if (e.key === 'Backspace' || e.key === 'Delete') {
      buffer.current = null;
      commit(withSegment(draft, key, null));
    } else if (key !== 'period' && /^\d$/.test(e.key)) typeDigit(key, index, e.key);
    else if (key === 'period' && e.key.length === 1) {
      const c = e.key.toLowerCase();
      if (c === 'a' || amLabel.toLowerCase().startsWith(c)) commit(withSegment(draft, key, 0));
      else if (c === 'p' || pmLabel.toLowerCase().startsWith(c)) commit(withSegment(draft, key, 1));
      else handled = false;
    } else if ((e.key === ':' || e.key === '.') && index < keys.length - 1) focusSegment(index + 1);
    else handled = false;
    if (handled) e.preventDefault();
  };

  const onRootMouseDown = (e: MouseEvent<HTMLDivElement>) => {
    if (disabled || (e.target as HTMLElement).getAttribute('role') === 'spinbutton') return;
    e.preventDefault();
    const empty = keys.findIndex((k) => display(k) === null);
    focusSegment(empty < 0 ? 0 : empty);
  };

  const label = (key: SegmentKey) =>
    t(key === 'hour' ? 'timePicker.hours' : key === 'minute' ? 'timePicker.minutes' : key === 'second' ? 'timePicker.seconds' : 'timePicker.period');

  return (
    <>
      <Field.Control
        id={id}
        disabled={disabled}
        render={(controlProps) => {
          const p = controlProps as ComponentProps<'div'> & { disabled?: boolean };
          const isDisabled = disabled || p.disabled;
          return (
            <div
              role="group"
              id={p.id}
              aria-label={ariaLabel ?? (ariaLabelledBy || p['aria-labelledby'] ? undefined : t('timePicker.label'))}
              aria-labelledby={ariaLabel ? undefined : (ariaLabelledBy ?? p['aria-labelledby'])}
              aria-describedby={ariaDescribedBy ?? p['aria-describedby']}
              data-invalid={invalid || outOfRange || undefined}
              data-disabled={isDisabled || undefined}
              onMouseDown={onRootMouseDown}
              onFocus={p.onFocus}
              onBlur={(e) => {
                buffer.current = null;
                p.onBlur?.(e);
              }}
              className={cn(s.root(), className)}
            >
              {icon && <Clock size={size === 'sm' ? 14 : 15} aria-hidden className={s.icon()} />}
              <div dir="ltr" className={s.segments()}>
                {keys.map((key, i) => {
                  const n = display(key);
                  const [lo, hi] = range(key);
                  const text = n === null ? '––' : key === 'period' ? (n ? pmLabel : amLabel) : pad(n);
                  return (
                    <span key={key} className="contents">
                      {i > 0 && key !== 'period' && (
                        <span aria-hidden className={s.separator()}>
                          :
                        </span>
                      )}
                      {key === 'period' && <span aria-hidden className="w-1" />}
                      <div
                        ref={(el) => {
                          segmentRefs.current[i] = el;
                        }}
                        role="spinbutton"
                        tabIndex={isDisabled ? -1 : 0}
                        aria-label={label(key)}
                        aria-valuemin={lo}
                        aria-valuemax={hi}
                        aria-valuenow={n ?? undefined}
                        aria-valuetext={n === null ? t('timePicker.empty') : text}
                        aria-disabled={isDisabled || undefined}
                        aria-readonly={readOnly || undefined}
                        aria-invalid={invalid || outOfRange || undefined}
                        data-placeholder={n === null || undefined}
                        data-segment={key}
                        onKeyDown={onKeyDown(key, i)}
                        onFocus={() => {
                          buffer.current = null;
                        }}
                        className={cn(s.segment(), key === 'period' ? 'min-w-[2.5ch]' : 'min-w-[2.2ch]')}
                      >
                        {text}
                      </div>
                    </span>
                  );
                })}
              </div>
            </div>
          );
        }}
      />
      {name && <input type="hidden" name={name} value={current ?? ''} />}
    </>
  );
}

export { TimePicker, type TimePickerProps } from './TimePicker';
export { parseTimeOfDay, formatTimeOfDay, localeHourCycle, type TimeOfDay } from './time-utils';
export { timePickerVariants, type TimePickerVariantProps } from './time-picker.variants';
export { doc as timePickerDoc } from './TimePicker.doc';

import { tv, type VariantProps } from '../../utils/tv';

/**
 * The brand field (recessed wrapper that owns border and focus outline) holding spinbutton
 * segments. The focused segment gets a primary tint; empty segments show a muted placeholder.
 */
export const timePickerVariants = tv({
  slots: {
    root: [
      'flex w-full min-w-0 items-center rounded-md border border-border bg-background text-foreground shadow-sm transition-colors motion-reduce:transition-none',
      'focus-within:border-primary/60 has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-focus-ring',
      'data-invalid:border-destructive/70',
      'data-disabled:cursor-not-allowed data-disabled:bg-secondary/50 data-disabled:text-muted-foreground',
    ],
    icon: 'pointer-events-none shrink-0 text-muted-foreground',
    segments: 'flex min-w-0 items-center tabular-nums',
    segment: [
      'rounded-[4px] px-0.5 text-center outline-none select-none caret-transparent',
      'focus:bg-primary/14 focus:text-primary-chip-text',
      'data-placeholder:text-muted-foreground aria-disabled:cursor-not-allowed',
    ],
    separator: 'px-px text-muted-foreground select-none',
  },
  variants: {
    size: {
      /** Follows `data-density` (comfortable = md). */
      auto: { root: 'h-control gap-tight px-field text-[13px]' },
      sm: { root: 'h-8 gap-2 px-2.5 text-[12px]' },
      md: { root: 'h-9 gap-2.5 px-3 text-[13px]' },
    },
  },
  defaultVariants: { size: 'auto' },
});

export type TimePickerVariantProps = VariantProps<typeof timePickerVariants>;

/** A time of day, 24-hour clock. */
export interface TimeOfDay {
  hours: number;
  minutes: number;
  seconds: number;
}

const pad = (n: number) => String(n).padStart(2, '0');

/** `"09:30"` / `"09:30:15"` → parts, or `null` when the string is not a valid 24-hour time. */
export function parseTimeOfDay(value: string | null | undefined): TimeOfDay | null {
  if (!value) return null;
  const m = /^(\d{1,2}):(\d{2})(?::(\d{2}))?$/.exec(value.trim());
  if (!m) return null;
  const hours = Number(m[1]);
  const minutes = Number(m[2]);
  const seconds = m[3] === undefined ? 0 : Number(m[3]);
  if (hours > 23 || minutes > 59 || seconds > 59) return null;
  return { hours, minutes, seconds };
}

/** Parts → `"HH:mm"`, or `"HH:mm:ss"` with `withSeconds`. */
export function formatTimeOfDay(parts: TimeOfDay, withSeconds = false): string {
  const base = `${pad(parts.hours)}:${pad(parts.minutes)}`;
  return withSeconds ? `${base}:${pad(parts.seconds)}` : base;
}

/** Seconds since midnight (for comparisons). */
export const timeToSeconds = (t: TimeOfDay) => t.hours * 3600 + t.minutes * 60 + t.seconds;

/** Copies the time of day onto a date (local time). */
export function withTimeOfDay(date: Date, t: TimeOfDay): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate(), t.hours, t.minutes, t.seconds);
}

/** The time of day of a date (local time). */
export const timeOfDay = (date: Date): TimeOfDay => ({ hours: date.getHours(), minutes: date.getMinutes(), seconds: date.getSeconds() });

/** 12 or 24: the clock a locale uses by default (Intl). */
export function localeHourCycle(locale?: string): 12 | 24 {
  try {
    const cycle = new Intl.DateTimeFormat(locale, { hour: 'numeric' }).resolvedOptions().hourCycle;
    return cycle === 'h11' || cycle === 'h12' ? 12 : 24;
  } catch {
    return 24;
  }
}

/** The locale's AM / PM labels (Intl `dayPeriod`), falling back to "AM" / "PM". */
export function dayPeriodLabels(locale?: string): [am: string, pm: string] {
  const label = (hour: number, fallback: string) => {
    try {
      const parts = new Intl.DateTimeFormat(locale, { hour: 'numeric', hourCycle: 'h12' }).formatToParts(new Date(2000, 0, 1, hour));
      return parts.find((p) => p.type === 'dayPeriod')?.value ?? fallback;
    } catch {
      return fallback;
    }
  };
  return [label(9, 'AM'), label(21, 'PM')];
}

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
